76	@RestController
77	@CrossOrigin(exposedHeaders = "errors, content-type")
78	@RequestMapping("/api")
79	public class OwnerRestControllerV1 implements OwnersApi {
80	
81	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
82	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
83	
84	    /**
85	     * Source of the {@link OwnerCreatedEvent}'s {@code seq}: a process-wide, monotonically increasing counter across
86	     * every owner create, so the structured audit events carry a strictly ordered sequence regardless of which
87	     * controller instance handled the request.
88	     */
89	    private static final AtomicLong OWNER_CREATED_SEQUENCE = new AtomicLong();
90	
91	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
92	    private static final int MAX_OWNERS_PER_CITY = 50;
93	
94	    /** Once a city already holds at least this many owners (but is not yet full), a further create there is flagged with a capacity warning. */
95	    private static final int CAPACITY_WARNING_THRESHOLD = 40;
96	
97	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
98	    private static final int MAX_OWNERS_PER_DAY = 100;
99	
100	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
101	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
102	
103	    /** Request header carrying the client-supplied idempotency key for a create; see {@link #addOwner}. */
104	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
105	
106	    /**
107	     * Remembers, per idempotency key, the id of the owner the first create with that key produced, so a repeated
108	     * create with an already-seen key returns the original owner instead of creating a duplicate.
109	     */
110	    private final Map<String, Integer> idempotentOwnerIds = new ConcurrentHashMap<>();
111	
112	    /** Fixed public holidays the business-day roll skips: the adjusted registration date never lands on one of these. */
113	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
114	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"), LocalDate.parse("2026-04-25"),
115	        LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
116	
117	    private final ClinicService clinicService;
118	
119	    private final OwnerMapper ownerMapper;
120	
121	    private final PetMapper petMapper;
122	
123	    private final VisitMapper visitMapper;
124	
125	    private final TelephoneNormalizer telephoneNormalizer;
126	
127	    private final AddressNormalizer addressNormalizer;
128	
129	    private final EmailNormalizer emailNormalizer;
130	
131	    private final IdentityKeyResolver identityKeyResolver;
132	
133	    private final HouseholdResolver householdResolver;
134	
135	    /** The current request, used to read the optional {@code Idempotency-Key} header on a create. */
136	    private final HttpServletRequest request;
137	
138	    public OwnerRestControllerV1(ClinicService clinicService,
139	                                 OwnerMapper ownerMapper,
140	                                 PetMapper petMapper,
141	                                 VisitMapper visitMapper,
142	                                 TelephoneNormalizer telephoneNormalizer,
143	                                 AddressNormalizer addressNormalizer,
144	                                 EmailNormalizer emailNormalizer,
145	                                 IdentityKeyResolver identityKeyResolver,
146	                                 HouseholdResolver householdResolver,
147	                                 HttpServletRequest request) {
148	        this.clinicService = clinicService;
149	        this.ownerMapper = ownerMapper;
150	        this.petMapper = petMapper;
151	        this.visitMapper = visitMapper;
152	        this.telephoneNormalizer = telephoneNormalizer;
153	        this.addressNormalizer = addressNormalizer;
154	        this.emailNormalizer = emailNormalizer;
155	        this.identityKeyResolver = identityKeyResolver;
156	        this.householdResolver = householdResolver;
157	        this.request = request;
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Override
162	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
163	        Collection<Owner> owners;
164	        if (lastName != null) {
165	            owners = this.clinicService.findOwnerByLastName(lastName);
166	        } else {
167	            owners = this.clinicService.findAllOwners();
168	        }
169	        if (owners.isEmpty()) {
170	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
171	        }
172	        owners.forEach(this::populateHouseholdMemberCount);
173	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
174	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
175	    }
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
180	        Owner owner = this.clinicService.findOwnerById(ownerId);
181	        if (owner == null) {
182	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
183	        }
184	        populateHouseholdMemberCount(owner);
185	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
186	    }
187	
188	    /**
189	     * Maps an owner to its DTO and stamps on the two derived values the mapper cannot produce on its own, each because
190	     * it depends on more than the single owner: the {@code identityKey} (see
191	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner, and the household-capped
192	     * {@code membershipLevel} (see {@link #cappedMembershipLevel}), which the mapper derives from the owner alone but
193	     * which the ceiling rule then caps against the owner's fellow household members. The capped level replaces the
194	     * mapper's uncapped one on the returned DTO.
195	     *
196	     * @param owner the owner to map
197	     * @return the owner DTO carrying its identity key and household-capped membership level
198	     */
199	    private OwnerDto toOwnerDto(Owner owner) {
200	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
201	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
202	        ownerDto.setMembershipLevel(cappedMembershipLevel(owner));
203	        return ownerDto;
204	    }
205	
206	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
207	    @Transactional
208	    @Override
209	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
210	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
211	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
212	            ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
213	            if (replay != null) {
214	                return replay;
215	            }
216	        }
217	        Owner owner = createOwner(ownerFieldsDto);
218	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
219	            idempotentOwnerIds.put(idempotencyKey, owner.getId());
220	        }
221	        return createdOwnerResponse(owner);
222	    }
223	
224	    /**
225	     * Replays the create that a previously-seen {@code Idempotency-Key} produced. When the key has already created an
226	     * owner that still exists, the original owner is returned with {@code 200 OK} instead of a duplicate being created;
227	     * otherwise (key unseen, or its owner has since been removed) {@code null} is returned and the create proceeds
228	     * normally.
229	     *
230	     * @param idempotencyKey the client-supplied idempotency key from the request header
231	     * @return a {@code 200 OK} response carrying the original owner, or {@code null} when there is nothing to replay
232	     */
233	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
234	        Integer existingId = idempotentOwnerIds.get(idempotencyKey);
235	        if (existingId == null) {
236	            return null;
237	        }
238	        Owner owner = this.clinicService.findOwnerById(existingId);
239	        if (owner == null) {
240	            return null;
241	        }
242	        populateHouseholdMemberCount(owner);
243	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
244	    }
245	
246	    /**
247	     * Creates and persists a new owner from an incoming payload, applying every creation rule in order. The payload is
248	     * normalized and validated (see {@link #normalizeAndValidate}), mapped to an owner and stamped with its fields
249	     * derived at creation (see {@link #populateDerivedFields}); the duplicate guard then runs against those derived
250	     * fields (see {@link #requireUniqueIdentity}) before the soft-duplicate
251	     * flag is recorded (see {@link #flagPossibleDuplicate}); the owner is saved, its transient household member count
252	     * is resolved (see {@link #populateHouseholdMemberCount}) and the creation is audited (see
253	     * {@link #auditOwnerCreated}). The returned owner carries its generated id and every field a response needs.
254	     *
255	     * @param ownerFieldsDto the incoming owner payload, mutated in place during normalization
256	     * @return the newly created, persisted owner
257	     */
258	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
259	        normalizeAndValidate(ownerFieldsDto);
260	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
261	        populateDerivedFields(owner, ownerFieldsDto);
262	        requireUniqueIdentity(owner);
263	        flagPossibleDuplicate(owner, ownerFieldsDto);
264	        this.clinicService.saveOwner(owner);
265	        populateHouseholdMemberCount(owner);
266	        auditOwnerCreated(owner);
267	        return owner;
268	    }
269	
270	    /**
271	     * Builds the {@code 201 Created} response for a newly created owner: the owner mapped to its DTO (carrying its
272	     * identity key, see {@link #toOwnerDto}) as the body, with a {@code Location} header pointing at the new owner's
273	     * canonical URL.
274	     *
275	     * @param owner the newly created, persisted owner
276	     * @return a {@code 201 Created} response carrying the owner DTO and its {@code Location} header
277	     */
278	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner) {
279	        OwnerDto ownerDto = toOwnerDto(owner);
280	        HttpHeaders headers = new HttpHeaders();
281	        headers.setLocation(UriComponentsBuilder.newInstance()
282	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
283	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
284	    }
285	
286	    /**
287	     * Emits the single audit line for a successfully created owner to the dedicated {@link #AUDIT} logger, recording
288	     * its id, customer code and registration date alongside the two values derived purely for the audit trail: the
289	     * membership level (see {@link MembershipLevelResolver#deriveMembershipLevel}) and the membership number, the
290	     * customer code suffixed with {@code -M} and the two-digit fiscal year of the registration date (see
291	     * {@link FiscalYearResolver#fiscalYear}).
292	     *
293	     * <p>In addition to the human-readable line, a single immutable structured event is emitted as JSON (see
294	     * {@link OwnerCreatedEvent}), carrying a monotonically increasing {@code seq} (see
295	     * {@link #OWNER_CREATED_SEQUENCE}), the owner's id, its current primary identifier (see
296	     * {@link #primaryIdentifier(Owner)}) and its membership level under the {@code OWNER_CREATED} event type.
297	     *
298	     * @param owner the newly created, persisted owner, with all its derived fields already in place
299	     */
300	    private void auditOwnerCreated(Owner owner) {
301	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
302	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
303	            MembershipLevelResolver.deriveMembershipLevel(owner),
304	            owner.getCustomerCode() + "-M" + String.format("%02d",
305	                FiscalYearResolver.fiscalYear(owner.getRegistrationDate()) % 100));
306	        OwnerCreatedEvent event = new OwnerCreatedEvent(OWNER_CREATED_SEQUENCE.incrementAndGet(),
307	            owner.getId(), primaryIdentifier(owner), cappedMembershipLevel(owner));
308	        AUDIT.info(event.toJson());
309	    }
310	
311	    /**
312	     * Returns the owner's current primary identifier — the value the structured {@link OwnerCreatedEvent} carries as the
313	     * owner's identity. Today that is the {@code customerCode}; when the customer code is later unified into a
314	     * {@code memberId}, this single method changes to return the member id and the event carries it instead, with no
315	     * other change to the emission.
316	     *
317	     * @param owner the newly created, persisted owner
318	     * @return the owner's current primary identifier
319	     */
320	    private String primaryIdentifier(Owner owner) {
321	        return owner.getCustomerCode();
322	    }
323	
324	    /**
325	     * Stamps onto a newly mapped owner every field derived at creation from the owner itself and from the owners that
326	     * already exist, in the order each field depends on. The {@code customerCode} is derived from the owner's own
327	     * fields (see {@link IdentityKeyResolver#deriveCustomerCode}); the {@code namesakeCount} (see
328	     * {@link #countNamesakes}), {@code bulkSignupWarning} (see {@link #computeBulkSignupWarning}) and
329	     * {@code capacityWarning} (see {@link #computeCapacityWarning}) are snapshots of the existing owners taken before
330	     * this owner is saved, so none counts the new owner itself; and the shared
331	     * {@code householdId} is assigned last (see {@link #assignHouseholdId}), derived deterministically from the owner's
332	     * last name and postcode, so it is in place before the owner's household membership level is capped (see
333	     * {@link #cappedMembershipLevel}). The owner is mutated in place; the caller applies the duplicate guards and saves it.
334	     *
335	     * @param owner          the newly mapped owner about to be saved
336	     * @param ownerFieldsDto the incoming owner payload
337	     */
338	    private void populateDerivedFields(Owner owner, OwnerFieldsDto ownerFieldsDto) {
339	        owner.setCustomerCode(deriveUniqueCustomerCode(owner));
340	        owner.setNamesakeCount(countNamesakes(owner));
341	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
342	        owner.setCapacityWarning(computeCapacityWarning(owner.getCity()));
343	        assignHouseholdId(owner);
344	    }
345	
346	    /**
347	     * Derives an owner's {@code customerCode} and de-duplicates it against the owners that already exist. The base code
348	     * is the pure derivation (see {@link IdentityKeyResolver#deriveCustomerCode}); when it collides with an existing
349	     * owner's {@code customerCode} it is suffixed with {@code -<n>}, taking the smallest {@code n} of 2 or more that
350	     * makes the whole code unique. Evaluated before the new owner is saved, so the collision check reflects only owners
351	     * that predate this create; distinct owners therefore always receive distinct customer codes.
352	     *
353	     * @param owner the newly mapped owner about to be saved, with its telephone already normalized
354	     * @return the de-duplicated customer code, unique across all existing owners
355	     */
356	    private String deriveUniqueCustomerCode(Owner owner) {
357	        String base = identityKeyResolver.deriveCustomerCode(owner);
358	        Collection<Owner> existing = this.clinicService.findAllOwners();
359	        String candidate = base;
360	        int n = 2;
361	        while (isCustomerCodeInUse(candidate, existing)) {
362	            candidate = base + "-" + n;
363	            n++;
364	        }
365	        return candidate;
366	    }
367	
368	    private boolean isCustomerCodeInUse(String customerCode, Collection<Owner> existing) {
369	        return existing.stream().anyMatch(other -> customerCode.equals(other.getCustomerCode()));
370	    }
371	
372	    /**
373	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
374	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
375	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
376	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
377	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
378	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
379	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
380	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
381	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
382	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
383	     * assigned (see {@link #requireUniqueIdentity}).
384	     *
385	     * @param ownerFieldsDto the incoming owner payload, mutated in place
386	     * @throws MissingOwnerFieldsException if any required field is missing or blank
387	     */
388	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
389	        normalizeAddress(ownerFieldsDto);
390	        validateRequiredFields(ownerFieldsDto);
391	        validatePostcode(ownerFieldsDto);
392	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
393	        ownerFieldsDto.setTelephone(telephone);
394	        requireCityHasCapacity(ownerFieldsDto.getCity());
395	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
396	        ownerFieldsDto.setRegistrationDate(registrationDate);
397	        requireDailyLimitNotReached(registrationDate);
398	        normalizeEmail(ownerFieldsDto);
399	    }
400	
401	    /**
402	     * Normalizes an owner's address to its canonical stored form and writes it back onto the payload. The structured
403	     * form is preferred over the flat one: when a non-blank {@code addressLine1} is supplied it (and the optional
404	     * {@code addressLine2}) are normalized (see {@link AddressNormalizer#normalize}) and the flat {@code address} is
405	     * recomposed as the normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
406	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized on its own and the
407	     * structured fields are cleared. Either way the canonical {@code address} is what gets stored and returned and what
408	     * every downstream reader uses; a blank result is uniformly treated as a missing address by the required-field
409	     * check that follows (an owner is valid when it supplies either a non-blank {@code addressLine1} or a non-blank flat
410	     * {@code address}). The payload is mutated in place so the caller can map and save it directly.
411	     *
412	     * @param ownerFieldsDto the incoming owner payload, mutated in place
413	     */
414	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
415	        String line1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
416	        String line2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
417	        if (!line1.isEmpty()) {
418	            ownerFieldsDto.setAddressLine1(line1);
419	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
420	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
421	        }
422	        else {
423	            ownerFieldsDto.setAddressLine1(null);
424	            ownerFieldsDto.setAddressLine2(null);
425	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
426	        }
427	    }
428	
429	    /**
430	     * Normalizes an owner's optional email to its canonical stored form and writes it back onto the payload. The
431	     * canonical form (see {@link EmailNormalizer#normalize}) is what gets stored and returned as {@code email} and what
432	     * every email comparison uses; a missing (blank or {@code null}) email is left untouched. The payload is mutated in
433	     * place so the caller can map and save it directly.
434	     *
435	     * @param ownerFieldsDto the incoming owner payload, mutated in place
436	     */
437	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
438	        ownerFieldsDto.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
439	    }
440	
441	    /**
442	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
443	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday, a Sunday
444	     * or a listed public holiday (see {@link #PUBLIC_HOLIDAYS}) it is rolled forward one day at a time until it lands on
445	     * a non-holiday weekday. The returned date is always a business day. A supplied date later than the current server
446	     * date is rejected.
447	     *
448	     * @param ownerFieldsDto the incoming owner payload
449	     * @return the effective registration date rolled forward onto a business day
450	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
451	     */
452	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
453	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
454	        if (effective == null) {
455	            effective = LocalDate.now();
456	        }
457	        else if (effective.isAfter(LocalDate.now())) {
458	            throw new FutureRegistrationDateException(
459	                "the registration date must not be later than the current server date");
460	        }
461	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY
462	            || PUBLIC_HOLIDAYS.contains(effective)) {
463	            effective = effective.plusDays(1);
464	        }
465	        return effective;
466	    }
467	
468	    /**
469	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
470	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
471	     * further owner may be created for that day.
472	     *
473	     * @param registrationDate the adjusted business-day registration date of the owner being created
474	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
475	     */
476	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
477	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
478	            throw new DailyOwnerLimitExceededException(
479	                "the maximum number of owners for today has already been reached");
480	        }
481	    }
482	
483	    /**
484	     * Counts how many existing owners already carry the given adjusted business-day {@code registrationDate}. Invoked
485	     * before the new owner is saved, so the count reflects only owners that predate this create. Shared by
486	     * {@link #requireDailyLimitNotReached} (the hard per-day cap) and {@link #computeBulkSignupWarning} (the soft
487	     * warning threshold) so both express the same per-day count in one place.
488	     *
489	     * @param registrationDate the adjusted business-day registration date to count owners for
490	     * @return the number of existing owners registered on that day
491	     */
492	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
493	        return this.clinicService.findAllOwners().stream()
494	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
495	            .count();
496	    }
497	
498	    /**
499	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
500	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
501	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
502	     * reflects only owners that predate it.
503	     *
504	     * @param registrationDate the adjusted business-day registration date of the owner being created
505	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
506	     */
507	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
508	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
509	    }
510	
511	    /**
512	     * Counts how many existing owners already share the given owner's first and last name, compared
513	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
514	     * create; it is zero when the owner's name is unique.
515	     *
516	     * @param owner the newly mapped owner about to be saved
517	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
518	     */
519	    private int countNamesakes(Owner owner) {
520	        String firstName = owner.getFirstName();
521	        String lastName = owner.getLastName();
522	        return (int) this.clinicService.findAllOwners().stream()
523	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
524	                && lastName.equalsIgnoreCase(existing.getLastName()))
525	            .count();
526	    }
527	
528	    /**
529	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
530	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
531	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
532	     *
533	     * <p>The address is checked after normalization has composed the canonical {@code address} from whichever form was
534	     * supplied, so a blank {@code address} here means the owner supplied neither a non-blank {@code addressLine1} nor a
535	     * flat {@code address}.
536	     *
537	     * @param ownerFieldsDto the owner payload to validate
538	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
539	     */
540	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
541	        List<String> missingFields = new ArrayList<>();
542	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
543	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
544	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
545	        requireText(missingFields, "city", ownerFieldsDto.getCity());
546	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
547	        if (!missingFields.isEmpty()) {
548	            throw new MissingOwnerFieldsException(missingFields);
549	        }
550	    }
551	
552	    private void requireText(List<String> missingFields, String fieldName, String value) {
553	        if (value == null || value.isBlank()) {
554	            missingFields.add(fieldName);
555	        }
556	    }
557	
558	    /**
559	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
560	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
561	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
562	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
563	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
564	     *
565	     * @param ownerFieldsDto the incoming owner payload
566	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
567	     */
568	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
569	        String postcode = ownerFieldsDto.getPostcode();
570	        if (postcode == null) {
571	            return;
572	        }
573	        Region region = Region.forCity(ownerFieldsDto.getCity());
574	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
575	            throw new InvalidPostcodeException(
576	                "postcode " + postcode + " is not valid for the city's region " + region.name());
577	        }
578	    }
579	
580	    /**
581	     * Rejects creating an owner whose whole derived {@code identityKey} (see
582	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner, so an owner is an identity
583	     * duplicate only when its normalized telephone, email and last-name Soundex all match another owner's. This single
584	     * identity key is now the sole duplicate rule: because the telephone is part of the key, owners that share only
585	     * their last name and postcode but carry different telephones have distinct keys and are not caught here — they are
586	     * created and flagged as a soft match instead (see {@link #flagPossibleDuplicate}), their membership level being
587	     * capped where they join an existing household (see {@link #cappedMembershipLevel}). Owners that have been
588	     * soft-deleted (see {@link #deleteOwner}) are ignored, so a matching identity that belongs only to a deleted owner
589	     * does not block the create.
590	     *
591	     * @param owner the newly mapped owner about to be saved, with its normalized fields already in place
592	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
593	     */
594	    private void requireUniqueIdentity(Owner owner) {
595	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
596	        boolean inUse = this.clinicService.findAllOwners().stream()
597	            .filter(existing -> !existing.isDeleted())
598	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
599	        if (inUse) {
600	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
601	        }
602	    }
603	
604	    /**
605	     * Flags a newly created owner as a possible (soft) duplicate. The owner has already cleared the hard-duplicate
606	     * guard (see {@link #requireUniqueIdentity}), so it is still being created; this only records a warning. A declared
607	     * household member (one created with {@code sharesHousehold} set to {@code true}) is never flagged: it deliberately
608	     * shares its household's last name and postcode, so it is not a suspected duplicate. Otherwise it is a possible
609	     * duplicate when some existing owner shares its last-name Soundex (see {@link SoundexResolver#soundex}) and its
610	     * postcode but has a different {@code identityKey}. When such an owner is found, {@code possibleDuplicate} is set to {@code true} and
611	     * {@code possibleDuplicateOf} to that existing owner's id (the first match in
612	     * {@link ClinicService#findAllOwners()} order); otherwise {@code possibleDuplicate} is {@code false} and
613	     * {@code possibleDuplicateOf} is left null. An owner created without a postcode can never soft-match.
614	     *
615	     * @param owner          the newly mapped owner about to be saved, with its normalized fields already in place
616	     * @param ownerFieldsDto the incoming owner payload
617	     */
618	    private void flagPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
619	        owner.setPossibleDuplicate(false);
620	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
621	            return;
622	        }
623	        String postcode = owner.getPostcode();
624	        if (postcode == null || postcode.isBlank()) {
625	            return;
626	        }
627	        for (Owner existing : this.clinicService.findAllOwners()) {
628	            if (isPossibleDuplicateOf(owner, existing)) {
629	                owner.setPossibleDuplicate(true);
630	                owner.setPossibleDuplicateOf(existing.getId());
631	                return;
632	            }
633	        }
634	    }
635	
636	    /**
637	     * Decides whether {@code existing} makes {@code owner} a possible (soft) duplicate: some other owner whose last-name
638	     * Soundex (see {@link SoundexResolver#soundex}) and postcode both match {@code owner}'s but whose derived
639	     * {@code identityKey} (see {@link IdentityKeyResolver#deriveIdentityKey}) differs. An equal identity key would make
640	     * the two a hard duplicate, already rejected by {@link #requireUniqueIdentity}; a differing key with a matching
641	     * name-sound and postcode — for instance two owners sharing a last name and postcode but carrying different
642	     * telephones — is the soft match this flags. The postcode-present guard is applied by the caller (see
643	     * {@link #flagPossibleDuplicate}), so {@code owner}'s postcode is non-blank here.
644	     *
645	     * @param owner    the newly mapped owner about to be saved, with its normalized fields already in place
646	     * @param existing an already-persisted owner to test the new owner against
647	     * @return {@code true} when {@code existing} makes {@code owner} a possible duplicate
648	     */
649	    private boolean isPossibleDuplicateOf(Owner owner, Owner existing) {
650	        return SoundexResolver.soundex(owner.getLastName()).equals(SoundexResolver.soundex(existing.getLastName()))
651	            && owner.getPostcode().equals(existing.getPostcode())
652	            && !identityKeyResolver.deriveIdentityKey(owner).equals(identityKeyResolver.deriveIdentityKey(existing));
653	    }
654	
655	    /**
656	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
657	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
658	     *
659	     * @param city the city of the owner being created
660	     * @throws OwnerCityFullException if the city already contains 50 or more owners
661	     */
662	    private void requireCityHasCapacity(String city) {
663	        if (countOwnersInCity(city) >= MAX_OWNERS_PER_CITY) {
664	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
665	        }
666	    }
667	
668	    /**
669	     * Counts how many existing owners already belong to the given {@code city}, compared case-insensitively. Invoked
670	     * before the new owner is saved, so the count reflects only owners that predate this create; it never counts the
671	     * new owner itself. Factored out of {@link #requireCityHasCapacity} so the per-city owner count is expressed in one
672	     * place, mirroring how {@link #countOwnersRegisteredOn} backs the per-day rules.
673	     *
674	     * @param city the city to count owners for
675	     * @return the number of existing owners in that city
676	     */
677	    private long countOwnersInCity(String city) {
678	        return this.clinicService.findAllOwners().stream()
679	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
680	            .count();
681	    }
682	
683	    /**
684	     * Determines whether creating an owner in the given city should carry a capacity warning. The warning is raised
685	     * when the city (compared case-insensitively) already holds between {@value #CAPACITY_WARNING_THRESHOLD} and
686	     * {@code MAX_OWNERS_PER_CITY - 1} owners, i.e. it is approaching but has not yet reached the hard per-city limit of
687	     * {@value #MAX_OWNERS_PER_CITY}. Evaluated before the new owner is saved, so the count reflects only owners that
688	     * predate this create; the hard rejection at the limit (see {@link #requireCityHasCapacity}) still runs.
689	     *
690	     * @param city the city of the owner being created
691	     * @return {@code true} when the city already holds 40 to 49 owners, {@code false} otherwise
692	     */
693	    private boolean computeCapacityWarning(String city) {
694	        long count = countOwnersInCity(city);
695	        return count >= CAPACITY_WARNING_THRESHOLD && count < MAX_OWNERS_PER_CITY;
696	    }
697	
698	    /**
699	     * Assigns the shared {@code householdId} for a newly mapped owner. The identifier is derived deterministically from
700	     * the owner's last name and postcode (see {@link HouseholdResolver#deriveHouseholdId}), so every owner sharing
701	     * those two fields resolves to the same stable value automatically, regardless of creation order and without any
702	     * explicit linking. An owner created without a postcode has no household and keeps a {@code null} identifier, so
703	     * such owners never match one another as a household.
704	     *
705	     * @param owner the newly mapped owner about to be saved
706	     */
707	    private void assignHouseholdId(Owner owner) {
708	        String postcode = owner.getPostcode();
709	        if (postcode == null || postcode.isBlank()) {
710	            owner.setHouseholdId(null);
711	            return;
712	        }
713	        owner.setHouseholdId(householdResolver.deriveHouseholdId(owner.getLastName(), postcode));
714	    }
715	
716	    /**
717	     * Returns an owner's household-capped membership level: the level the {@link MembershipLevelResolver} derives from
718	     * the owner (see {@link MembershipLevelResolver#deriveMembershipLevel(Owner)}), lowered where necessary so it never
719	     * exceeds one above the highest capped level among the owner's <em>existing</em> household members — the members
720	     * that predate the owner, identified as those sharing its non-null {@code householdId} with a smaller id. When the
721	     * owner has no such existing household member (it is the first in its household, or has no household at all) no cap
722	     * applies and the derived level is returned unchanged. The owner's transient household member count is populated
723	     * first (see {@link #populateHouseholdMemberCount}) so the derived level reflects the current household size.
724	     *
725	     * @param owner the owner whose capped membership level should be computed
726	     * @return the membership level, capped at one above the existing household maximum
727	     */
728	    private int cappedMembershipLevel(Owner owner) {
729	        populateHouseholdMemberCount(owner);
730	        int level = MembershipLevelResolver.deriveMembershipLevel(owner);
731	        Integer cap = householdMembershipLevelCap(owner);
732	        return cap == null ? level : Math.min(level, cap);
733	    }
734	
735	    /**
736	     * Computes the ceiling the {@link #cappedMembershipLevel level-ceiling rule} imposes on a new owner: one above the
737	     * highest capped membership level among the owner's existing household members, or {@code null} when there is none.
738	     * An existing household member is an owner sharing this owner's non-null {@code householdId} whose id is smaller (so
739	     * it predates this owner); their levels are read with {@link #cappedMembershipLevel}, so each member's own ceiling
740	     * is respected in turn. An owner with no household ({@code null} householdId), no id yet, or no existing household
741	     * member has no cap.
742	     *
743	     * @param owner the owner whose household level cap should be computed
744	     * @return one above the existing household maximum level, or {@code null} when no cap applies
745	     */
746	    private Integer householdMembershipLevelCap(Owner owner) {
747	        String householdId = owner.getHouseholdId();
748	        Integer id = owner.getId();
749	        if (householdId == null || id == null) {
750	            return null;
751	        }
752	        Integer maxLevel = null;
753	        for (Owner member : this.clinicService.findAllOwners()) {
754	            Integer memberId = member.getId();
755	            if (memberId != null && memberId < id && householdId.equals(member.getHouseholdId())) {
756	                int memberLevel = cappedMembershipLevel(member);
757	                maxLevel = (maxLevel == null) ? memberLevel : Math.max(maxLevel, memberLevel);
758	            }
759	        }
760	        return maxLevel == null ? null : maxLevel + 1;
761	    }
762	
763	    /**
764	     * Returns the owners that belong to the given owner's household: those sharing the same non-null
765	     * {@code householdId}. An owner with no household ({@code null} householdId) is a household of one and is returned on
766	     * its own. The lookup runs against {@link ClinicService#findAllOwners()} and, like the household member count it
767	     * backs (see {@link #populateHouseholdMemberCount}), does not exclude soft-deleted owners. When the owner has
768	     * already been saved it is itself among the members returned.
769	     *
770	     * @param owner the owner whose household members should be resolved
771	     * @return the members of the owner's household, never empty
772	     */
773	    private List<Owner> householdMembers(Owner owner) {
774	        String householdId = owner.getHouseholdId();
775	        if (householdId == null) {
776	            return List.of(owner);
777	        }
778	        return this.clinicService.findAllOwners().stream()
779	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
780	            .toList();
781	    }
782	
783	    /**
784	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
785	     * household (see {@link #householdMembers}), i.e. those sharing the same non-null {@code householdId} (including the
786	     * owner itself). An owner with no household is counted as a household of one.
787	     *
788	     * @param owner the owner whose household size should be resolved
789	     */
790	    private void populateHouseholdMemberCount(Owner owner) {
791	        owner.setHouseholdMemberCount(householdMembers(owner).size());
792	    }
793	
794	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
795	    @Override
796	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
797	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
798	        if (currentOwner == null) {
799	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
800	        }
801	        validatePostcode(ownerFieldsDto);
802	        currentOwner.setAddress(ownerFieldsDto.getAddress());
803	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
804	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
805	        currentOwner.setCity(ownerFieldsDto.getCity());
806	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
807	        currentOwner.setLastName(ownerFieldsDto.getLastName());
808	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
809	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
810	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
811	        this.clinicService.saveOwner(currentOwner);
812	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
813	    }
814	
815	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
816	    @Transactional
817	    @Override
818	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
819	        Owner owner = this.clinicService.findOwnerById(ownerId);
820	        if (owner == null) {
821	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
822	        }
823	        owner.setDeleted(true);
824	        this.clinicService.saveOwner(owner);
825	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
826	    }
827	
828	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
829	    @Override
830	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
831	        Owner owner = this.clinicService.findOwnerById(ownerId);
832	        if (owner == null) {
833	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
834	        }
835	        HttpHeaders headers = new HttpHeaders();
836	        Pet pet = petMapper.toPet(petFieldsDto);
837	        owner.setId(ownerId);
838	        pet.setOwner(owner);
839	        pet.getType().setName(null);
840	        this.clinicService.savePet(pet);
841	        PetDto petDto = petMapper.toPetDto(pet);
842	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
843	            .buildAndExpand(pet.getId()).toUri());
844	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
845	    }
846	
847	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
848	    @Override
849	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
850	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
851	        if (currentOwner != null) {
852	            Pet currentPet = this.clinicService.findPetById(petId);
853	            if (currentPet != null) {
854	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
855	                currentPet.setName(petFieldsDto.getName());
856	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
857	                this.clinicService.savePet(currentPet);
858	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
859	            }
860	        }
861	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
862	    }
863	
864	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
865	    @Override
866	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
867	        HttpHeaders headers = new HttpHeaders();
868	        Visit visit = visitMapper.toVisit(visitFieldsDto);
869	        Pet pet = new Pet();
870	        pet.setId(petId);
871	        visit.setPet(pet);
872	        this.clinicService.saveVisit(visit);
873	        VisitDto visitDto = visitMapper.toVisitDto(visit);
874	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
875	            .buildAndExpand(visit.getId()).toUri());
876	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
877	    }
878	
879	
880	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
881	    @Override
882	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
883	        Owner owner = this.clinicService.findOwnerById(ownerId);
884	        if (owner != null) {
885	            Pet pet = owner.getPet(petId);
886	            if (pet != null) {
887	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
888	            }
889	        }
890	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
891	    }
892	}
